import java.util.*;
import java.io.*;

public class Main {
    static long n_value, total_nodes, total_sum, result_sum;
    static List<Long>[] storage = new ArrayList[15];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n_value = Long.parseLong(br.readLine());
        for (int i = 0; i < 15; i++) {
            storage[i] = new ArrayList<>();
        }
        build_tree(0, 0);
        for (int i = 0; i <= 7; i++) {
            Collections.sort(storage[i]);
        }
        total_nodes = 0;
        for (long i = 1; i <= 9; i++) {
            evaluate(i);
        }
        System.out.println(result_sum);
    }

    static void build_tree(int level, long num) {
        if (level == 7) return;
        total_nodes++;
        long val = ((total_nodes - num) % 998244353 + 998244353) % 998244353;
        storage[level].add(val);
        total_sum = (total_sum + val) % 1000000007;
        for (int digit = 0; digit <= 9; digit++) {
            build_tree(level + 1, num * 10 + digit);
        }
    }

    static void evaluate(long x) {
        if (x > n_value) return;
        if (x * 1000000 + 999999 <= n_value && x * 10000000 > n_value) {
            long current_total = total_nodes;
            int[] sizeArr = new int[7];
            long[] diffArr = new long[7];
            for (int i = 0, factor = 1; i <= 6; i++, factor *= 10) {
                int size = storage[i].size();
                sizeArr[i] = size;
                long diff = ((current_total - x * factor) % 998244353 + 998244353) % 998244353;
                int pos = lowerBound(storage[i], 1000000000 - diff);
                diffArr[i] = diff;
                result_sum = (result_sum + diff * size + total_sum) % 1000000007;
                long subtractVal = (998244353L * (size - pos)) % 1000000007;
                result_sum = (result_sum - subtractVal + 1000000007) % 1000000007;
                current_total += size;
            }
            return;
        }
        total_nodes++;
        long addVal = ((total_nodes - x) % 998244353 + 998244353) % 998244353;
        result_sum = (result_sum + addVal) % 1000000007;
        for (int digit = 0; digit <= 9; digit++) {
            evaluate(x * 10 + digit);
        }
    }

    static int lowerBound(List<Long> list, long key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
